 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Label 4-connected components of the foreground.
    comp = [[-1] * w for _ in range(h)]
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 1 and comp[r][c] < 0:
                k = len(comps); q = deque([(r, c)]); comp[r][c] = k; cells = []
                while q:
                    y, x = q.popleft(); cells.append((y, x))
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny, nx = y+dy, x+dx
                        if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 1 and comp[ny][nx] < 0:
                            comp[ny][nx] = k; q.append((ny,nx))
                comps.append(cells)
    # Flood-fill all background connected to the edge; the remaining zeros are cavities.
    exterior = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == 0 and not exterior[r][c]: exterior[r][c] = True; q.append((r,c))
    for c in range(w):
        for r in (0, h-1):
            if grid[r][c] == 0 and not exterior[r][c]: exterior[r][c] = True; q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and not exterior[nr][nc]:
                exterior[nr][nc]=True; q.append((nr,nc))
    # A foreground component is active only if it borders a genuinely enclosed zero.
    active = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and not exterior[r][c]:
                for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                    nr,nc=r+dr,c+dc
                    if 0<=nr<h and 0<=nc<w and comp[nr][nc]>=0:
                        active.add(comp[nr][nc])
    # Color the one-cell boundary layer: 3 on the cavity side, 2 on the outside.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0: continue
            touching = set()
            for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                nr,nc=r+dr,c+dc
                if 0<=nr<h and 0<=nc<w and comp[nr][nc] in active:
                    touching.add(comp[nr][nc])
            if touching:
                out[r][c] = 2 if exterior[r][c] else 3
    return out
